    @staticmethod
    def track_point(g):
        """A point on a route (preferably under a live enemy) for abilities that need a target point."""
        es = g.get_enemy_manager().get_enemies()
        from_ = (g.get_map().get_routes()[0].position_at((300 + RenderSoak.RNG.next_int(400))) if (len(es) == 0) else es[RenderSoak.RNG.next_int(len(es))].get_position())
        tp = g.get_effects().nearest_track_point(from_)
        return from_ if (tp is None) else tp.position
