        for x in range(30, GameMap.WIDTH, 13):
            for y in range(30, GameMap.HEIGHT, 13):
                _j_add(spots, Vec(x, y))
        _j.shuffle(spots, _j.Random(3))
        for round_ in range(2):
            for t in TowerType.purchasable():
                if (round_ == 1) and t.is_hero():
                    continue
                r = catalog.get(t).radius
                for p in spots:
                    if map_.is_buildable(p, r) and g.get_tower_manager().can_place(t, p):
                        if round_ == 0:
                            RenderSoak.app.get_game_screen().begin_placing(t)
                            RenderSoak.app.get_game_screen().mouse_moved((p.x + Ui.WORLD_X), (p.y + Ui.WORLD_Y))
                            RenderSoak.app.get_game_screen().get_side_panel().update(0.01)
                            RenderSoak.paint_quiet()
                            RenderSoak.app.get_game_screen().mouse_pressed((p.x + Ui.WORLD_X), (p.y + Ui.WORLD_Y), False)
                            RenderSoak.app.get_game_screen().begin_placing(None)
                        else:
                            g.place_tower(t, p)
                        break
